            depths[i] = fnCount; commented[i] = false;
            i++; prev = c; continue;
        }
        if (c === '/' && source.charAt(i + 1) === '/') { inLine = true; depths[i] = fnCount; commented[i] = true; i++; prev = c; continue; }
