            var deferred = gate().classifyRequires(source).filter(function (c) {
                return c.deferred;
            });
            assert.deepEqual(deferred, [],
                'reintroducing a lazy/deferred require in ' + path +
                ' re-opens gh-823 — require it at load time (top level)');
        });
    });

