 *                                (e.g. { file_read: fn, jira_search_by_jql: fn })
 *                                These are injected as local vars that shadow globals.
 * @returns {Object} module.exports
 */
function loadModule(path, requireFn, mocks) {
    var code = file_read({ path: path });
